import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"1956年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1956年/核心总结.md","filePath":"01_letters/1956年/核心总结.md"}'),i={name:"01_letters/1956年/核心总结.md"};function n(s,a,l,_,d,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1956年-核心总结" tabindex="-1">1956年 核心总结 <a class="header-anchor" href="#_1956年-核心总结" aria-label="Permalink to &quot;1956年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1956年是巴菲特投资合伙企业的创立元年。当年5月1日，巴菲特在奥马哈创立了自己的第一家合伙企业——巴菲特联合有限公司（Buffett Associates, Ltd.）。虽然1956年并非完整年度，但这是巴菲特日后商业帝国的起点。他以仅为数不多的启动资金开始，逐步建立起一套成熟的投资方法论。年底时，合伙企业已为早期合伙人创造了正回报，验证了其投资策略的有效性。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>1956年5月1日，巴菲特正式创立合伙企业，彼时他年仅25岁，尚在为自己的导师本杰明·格雷厄姆工作。合伙企业成立之初，共有7位有限合伙人（Limited Partners）加入，他们多为巴菲特的家庭成员和挚友，总投入资金为10.51万美元（约合人民币75万元，按当时汇率估算）。巴菲特本人作为普通合伙人（General Partner），象征性地投入了少量自有资金。这7位合伙人包括他的姐姐、姑妈、大学同学及其母亲等，共同构成了巴菲特最早的投资阵营。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特在创立之初即明确了其核心投资原则：他不会承诺任何具体的投资结果，而是以道琼斯工业平均指数作为衡量基准。他强调长期投资的重要性，主张通过深入研究企业内在价值，寻找被市场低估的标的。他明确表示，合伙企业的目标是在长期（至少三年以上）跑赢道琼斯指数，而非追求短期的高收益。这些原则在日后数十年的信中被反复重申，成为巴菲特投资哲学的基石。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>本杰明·格雷厄姆是这一时期对巴菲特影响最深的人物。作为&quot;价值投资之父&quot;，格雷厄姆的《证券分析》和《聪明的投资者》是巴菲特投资思想的源头。巴菲特在1951年便参加了格雷厄姆在哥伦比亚大学的课程，并成为其最优秀的学生之一。1954年至1956年间，巴菲特曾在格雷厄姆-纽曼公司工作，这段经历让他深度实践了老师的价值投资方法。此外，巴菲特的妻子苏珊以及家人对他早期创业的信任与支持，同样是不可忽视的力量。</p>',9)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
